// Trim stray spaces from column headers (e.g. "Product ")
const clean = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k.trim(), v]));
// Inventory = "Get Inventory Data" (Inventory sheet); Sales = "Get Sales Data" (Sheet3)
const inv = $('Get Inventory Data').all().map(i => clean(i.json));
const sales = $('Get Sales Data').all().map(i => clean(i.json));
const DAYS = 14;

const sold = {};
for (const s of sales) sold[s.SKU] = (sold[s.SKU] || 0) + Number(s.Qty);

const rows = inv.map(p => {
  const stock = Number(p.Stock);
  const level = Number(p['Reorder Level']);
  const units = sold[p.SKU] || 0;
  const perDay = units / DAYS;
  const daysLeft = perDay > 0 ? Math.round(stock / perDay) : null;
  return { sku: p.SKU, product: p.Product, stock, level, units, perDay: +perDay.toFixed(2), daysLeft };
});

return [{ json: {
  lowStock: rows.filter(r => r.stock <= r.level),
  bestSellers: [...rows].sort((a, b) => b.units - a.units).filter(r => r.units > 0).slice(0, 3),
  runOutSoon: rows.filter(r => r.daysLeft !== null && r.daysLeft <= 14),
  slowMoving: rows.filter(r => r.units > 0 && r.units <= 2 && r.stock > r.level * 2),
  overstocked: rows.filter(r => r.units === 0 && r.stock > r.level * 3)
}}];

